import { Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import * as Textarea from "../../ui/shadcn-textarea";

// MODEL

export const Model = S.Struct({});
export type Model = typeof Model.Type;

// MESSAGE

export const Message = S.Never;
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{}, []];

// UPDATE

export const update = (
  model: Model,
  _message: Message
): readonly [Model, readonly Command.Command<Message>[]] => [model, []];

// VIEW

export const view = Submodel.defineView<Model, Message>((): Html => {
  const h = html<Message>();

  return Textarea.view<Message>({
    id: "feedback",
    value: "",
    rows: 4,
    placeholder: "تعليقاتك تساعدنا على التحسين...",
    toView: (attributes) =>
      h.div(
        [h.Dir("rtl"), h.Class("w-full max-w-xs space-y-2")],
        [
          h.label(
            [
              ...attributes.label,
              h.Dir("rtl"),
              h.Class(Textarea.shadcnTextareaLabelClasses),
            ],
            ["التعليقات"]
          ),
          h.textarea(
            [
              ...attributes.textarea,
              h.Dir("rtl"),
              h.Class(Textarea.shadcnTextareaClasses),
            ],
            []
          ),
          h.p(
            [
              ...attributes.description,
              h.Dir("rtl"),
              h.Class(Textarea.shadcnTextareaDescriptionClasses),
            ],
            ["شاركنا أفكارك حول خدمتنا."]
          ),
        ]
      ),
  });
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as Example from "./main";

describe("Shadcn Textarea RTL example", () => {
  test("renders the origin Arabic RTL textarea demo", () => {
    Scene.scene(
      { update: Example.update, view: Example.view },
      Scene.with(Example.init()[0]),
      Scene.expect(Scene.text("التعليقات")).toExist(),
      Scene.expect(Scene.placeholder("تعليقاتك تساعدنا على التحسين...")).toHaveAttr(
        "dir",
        "rtl"
      ),
      Scene.expect(Scene.text("شاركنا أفكارك حول خدمتنا.")).toExist(),
      Scene.expect(Scene.placeholder("تعليقاتك تساعدنا على التحسين...")).not.toHaveHandler(
        "input"
      )
    );
  });
});
